// Define 4 carousel slides for cloudless.gr with custom comfyPrompt
const slides = [
  {
    "title": "Stop Overpaying For Gated Infrastructure That Sits Idle.",
    "subtitle": "The framework we use at cloudless.gr to transition teams away from enterprise bloat to Serverless architecture.",
    "comfyPrompt": "hyper-detailed sleek global server rack networking grid"
  },
  {
    "title": "Servers sitting idle 90% of the time are an absolute revenue drain.",
    "subtitle": "Thinking you need dedicated infrastructure early on results in massive bills. We pivot architectures to high-performance event-driven systems that drop to completely zero cost when traffic falls.",
    "comfyPrompt": "abstract cloud computing edge processing visualization"
  },
  {
    "title": "Global optimization on Cloudflare with zero latency friction.",
    "subtitle": "Deploy your code right to edge boundaries. By utilizing Cloudflare Workers, D1, and R2 databases, apps run with a 12ms global p95 profile while slashing infrastructure costs by 60% to 80%.",
    "comfyPrompt": "global edge network with nodes worldwide, interconnected cloudflare locations, data flowing between points, neon cyan connections on dark background, futuristic global connectivity visualization"
  },
  {
    "title": "Guaranteed measurable execution progress inside 14 days.",
    "subtitle": "Startups require speed, not multi-month roadmaps. We engineer and map transparent, production-ready deliverables within a 14-day execution sprint or keep refining until it hits exact specification.",
    "comfyPrompt": "velocity and speed concept, racing lines, motion blur effect, checkered flag, timing gauges, vibrant orange and yellow accents, dynamic motion visualization, high-tech speedometer"
  }
];

return [{ json: { slides: slides } }];

// Base ComfyUI workflow
const baseWorkflow = {
  "3": {
    "inputs": { "seed": Math.floor(Math.random() * 10000000) },
    "class_type": "KSampler"
  },
  "4": {
    "inputs": { "ckpt_name": "juggernaut_xl_v8Rundiffusion.safetensors" },
    "class_type": "CheckpointLoaderSimple"
  },
  "6": {
    "inputs": {
      "text": "", // Will be replaced with slide.comfyPrompt
      "clip": ["4", 1]
    },
    "class_type": "CLIPTextEncode"
  },
  "7": {
    "inputs": { "text": "blurry, low quality, disfigured text, bad hands, noisy background, neon green light bloat, oversaturated, human face, portrait, illustration" },
    "class_type": "CLIPTextEncode"
  },
  "8": {
    "inputs": { "width": 1024, "height": 1024, "batch_size": 1 },
    "class_type": "EmptyLatentImage"
  },
  "9": {
    "inputs": { "samples": ["3", 0], "vae": ["4", 2] },
    "class_type": "VAEDecode"
  },
  "10": {
    "inputs": { "filename_prefix": "cloudless-carousel-wsl" },
    "class_type": "SaveImage"
  }
};

// Get current slide from context
const slide = $json;

// Create a deep copy of the workflow
const workflow = JSON.parse(JSON.stringify(baseWorkflow));

// Inject the slide's comfyPrompt into Node 6
workflow["6"].inputs.text = slide.comfyPrompt;

return [{
  json: {
    prompt: workflow,
    client_id: `n8n-k3s-agent-slide-${slide.title ? slide.title.replace(/[^a-zA-Z0-9]/g, '_').substring(0, 20) : 'unknown'}`,
    slideData: slide // Pass through slide data for later use
  }
}];

const historyData = $json;

if (historyData && historyData.outputs && historyData.outputs["10"]) {
  const filename = historyData.outputs["10"].images[0].filename;
  return [{ json: { status: "completed", filename: filename, slideData: $node["Prepare ComfyUI Payload"].json.slideData } }];
}
return [{ json: { status: "processing" } }];
